declare const reducer: unknown;
declare function configureStore(options: unknown): unknown;
export const store = configureStore({ reducer });
export const createTestStore = () => configureStore({ reducer });

declare function useQuery(options: unknown): unknown;
declare function fetchTodo(id: string): unknown;
declare const todoId: string;
export const useTodo = () => useQuery({ queryKey: ['todo', todoId], queryFn: () => fetchTodo(todoId) });
